def write(name,title,body):
    (ROOT/name).write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+css+'</style></head><body>'+nav+'<main>'+body+'</main></body></html>',encoding='utf-8')
text=(ROOT/'独立远程电脑PRD.md').read_text(encoding='utf-8-sig')
